}
# normalize line endings to LF so multi-line patterns match regardless of
# how this script was saved
foreach ($k in @($files.Keys)) { $files[$k] = $files[$k].Replace("`r`n", "`n") }

function Find-Line([string]$text, [string]$pattern) {
    $pattern = $pattern.Replace("`r`n", "`n")
    $idx = $text.IndexOf($pattern, [System.StringComparison]::Ordinal)
    if ($idx -lt 0) { throw "symbol not found: $pattern" }
    $line = ($text.Substring(0, $idx) -split "`n").Count
    return @{ idx = $idx; line = $line }
}

# Extract a brace-balanced block starting at the line containing $pattern.
function Extract-Block([string]$text, [string]$pattern, [string]$label) {
    $loc = Find-Line $text $pattern
    $i = $text.IndexOf("{", $loc.idx)
    if ($i -lt 0) { throw "no opening brace for $label" }
    $depth = 0; $j = $i
    while ($j -lt $text.Length) {
        $c = $text[$j]
        if ($c -eq '{') { $depth++ }
        elseif ($c -eq '}') { $depth--; if ($depth -eq 0) { break } }
        $j++
    }
    if ($depth -ne 0) { throw "unbalanced braces for $label" }
    # include the remainder of the closing line (e.g. "} PredictionMode;")
    $lineEnd = $text.IndexOf("`n", $j)
    if ($lineEnd -lt 0) { $lineEnd = $text.Length }
    $end = $lineEnd
    $body = $text.Substring($loc.idx, $end - $loc.idx).TrimEnd()
    return @{ body = $body; line = $loc.line }
}

# Extract a preprocessor macro / scalar definition: from the pattern through
# its logical end (backslash continuations included), never crossing into
# unrelated constructs.
function Extract-Macro([string]$text, [string]$pattern, [string]$label) {
    $loc = Find-Line $text $pattern
    $lineStart = $text.LastIndexOf("`n", $loc.idx) + 1
    $pos = $lineStart
    while ($true) {
        $lineEnd = $text.IndexOf("`n", $pos)
        if ($lineEnd -lt 0) { $pos = $text.Length; break }
        $line = $text.Substring($pos, $lineEnd - $pos).TrimEnd("`r")
        $pos = $lineEnd + 1
        if (-not $line.TrimEnd().EndsWith('\')) { break }
    }
    $body = $text.Substring($lineStart, $pos - $lineStart).TrimEnd()
    return @{ body = $body; line = $loc.line }
}

# Extract a verbatim LINE RANGE: from the line containing $start through the
# line containing $end (both included). For declaration blocks that contain
# no braces, where Extract-Block cannot find the extent.
function Extract-Lines([string]$text, [string]$start, [string]$end, [string]$label) {
    $a = Find-Line $text $start
    $b = Find-Line $text $end
    if ($b.idx -lt $a.idx) { throw "end pattern before start pattern for $label" }
    $lineEnd = $text.IndexOf("`n", $b.idx)
    if ($lineEnd -lt 0) { $lineEnd = $text.Length }
    $body = $text.Substring($a.idx, $lineEnd - $a.idx).TrimEnd()
    return @{ body = $body; line = $a.line }
}

function Emit-Lines([string]$file, [string]$start, [string]$end, [string]$label) {
    $r = Extract-Lines $files[$file] $start $end $label
    Emit ""
    Emit "// ==== SVT-AV1 $file :$($r.line) - $label (verbatim line-range extract; do not edit) ===="
    Emit $r.body
}

function Emit-Macro([string]$file, [string]$pattern, [string]$label) {
    $r = Extract-Macro $files[$file] $pattern $label
    Emit ""
    Emit "// ==== SVT-AV1 $file :$($r.line) - $label (verbatim extract; do not edit) ===="
    Emit $r.body
}

$out = New-Object System.Text.StringBuilder
function Emit([string]$s) { [void]$out.AppendLine($s) }

function Emit-Verbatim([string]$file, [string]$pattern, [string]$label) {
    $r = Extract-Block $files[$file] $pattern $label
    Emit ""
    Emit "// ==== SVT-AV1 $file :$($r.line) - $label (verbatim extract; do not edit) ===="
    Emit $r.body
}

